CREATE TABLE app_user (id UUID PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(40), active BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE app_role (id UUID PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL, description VARCHAR(255), active BOOLEAN NOT NULL);
CREATE TABLE customer (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, contact_person VARCHAR(160), phone VARCHAR(40), email VARCHAR(160), active BOOLEAN NOT NULL);
CREATE TABLE department (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, description VARCHAR(255), active BOOLEAN NOT NULL);
CREATE TABLE location (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, address VARCHAR(255), latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, active BOOLEAN NOT NULL);
CREATE TABLE project (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, department_id UUID, active BOOLEAN NOT NULL);
CREATE TABLE driver (id UUID PRIMARY KEY, employee_number VARCHAR(60) UNIQUE NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(40), email VARCHAR(160), status VARCHAR(40) NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE vehicle_category (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, description VARCHAR(255), active BOOLEAN NOT NULL);
CREATE TABLE vehicle_type (id UUID PRIMARY KEY, category_id UUID NOT NULL, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, description VARCHAR(255), active BOOLEAN NOT NULL);
CREATE TABLE vehicle (id UUID PRIMARY KEY, registration_number VARCHAR(80) UNIQUE NOT NULL, chassis_number VARCHAR(120), engine_number VARCHAR(120), category_id UUID NOT NULL, type_id UUID NOT NULL, manufacturer VARCHAR(120), model VARCHAR(120), manufacture_year INT, ownership_type VARCHAR(40) NOT NULL, operational_status VARCHAR(40) NOT NULL, current_odometer_km DOUBLE PRECISION, engine_hours DOUBLE PRECISION, capacity_kg DOUBLE PRECISION, active BOOLEAN NOT NULL);
CREATE TABLE route (id UUID PRIMARY KEY, code VARCHAR(40) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, origin_location_id UUID NOT NULL, destination_location_id UUID NOT NULL, planned_distance_km DOUBLE PRECISION, estimated_duration_minutes INT, active BOOLEAN NOT NULL);
CREATE TABLE trip (id UUID PRIMARY KEY, trip_number VARCHAR(60) UNIQUE NOT NULL, customer_id UUID, department_id UUID, project_id UUID, route_id UUID, priority VARCHAR(30) NOT NULL, status VARCHAR(40) NOT NULL, origin_location_id UUID NOT NULL, destination_location_id UUID NOT NULL, requested_start_time TIMESTAMP WITH TIME ZONE NOT NULL, requested_end_time TIMESTAMP WITH TIME ZONE NOT NULL, required_vehicle_type_id UUID, required_capacity_kg DOUBLE PRECISION, cargo_description VARCHAR(500), passenger_count INT, customer_instructions VARCHAR(1000), notes VARCHAR(1000), vehicle_id UUID, driver_id UUID, actual_start_time TIMESTAMP WITH TIME ZONE, actual_end_time TIMESTAMP WITH TIME ZONE, start_odometer_km DOUBLE PRECISION, end_odometer_km DOUBLE PRECISION, completion_remarks VARCHAR(1000), created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_trip_status ON trip(status);
CREATE INDEX idx_trip_period ON trip(requested_start_time, requested_end_time);
CREATE INDEX idx_vehicle_status ON vehicle(active, operational_status);
CREATE INDEX idx_driver_status ON driver(active, status);
